const int N = 1e5 + 100;
const int ITERS = 60;
const double eps = 1e-9;
double sqr(double x) { return x * x; }
struct point {
  double x, y;
  point() {}
  point(double _x, double _y) : x(_x), y(_y) {}
  friend point operator/(const point& p, double d) {
    return point(p.x / d, p.y / d);
  }
  friend point operator+(const point& a, const point& b) {
    return point(a.x + b.x, a.y + b.y);
  }
  friend point operator-(const point& a, const point& b) {
    return point(a.x - b.x, a.y - b.y);
  }
  friend point operator*(const point& p, double d) {
    return point(p.x * d, p.y * d);
  }
  double norm() const { return sqrt(sqr(x) + sqr(y)); }
};
int n, k;
vector<pair<point, pair<int, int>>> p;
bool can[N];
double x[N], y[N];
void init() {}
bool eq(double a, double b) { return fabs(a - b) < eps; }
int half(const point& p) {
  if (p.y > -eps) {
    return 0;
  }
  return 1;
}
double vec(const point& a, const point& b) { return a.x * b.y - b.x * a.y; }
bool vec_cmp(const pair<point, pair<int, int>>& a,
             const pair<point, pair<int, int>>& b) {
  int ha = half(a.first), hb = half(b.first);
  if (ha != hb) {
    return ha < hb;
  }
  double v = vec(a.first, b.first);
  if (v > eps) {
    return true;
  }
  if (v < -eps) {
    return false;
  }
  return a.second < b.second;
}
void build_inter(point p, double r, point* res) {
  point mid = p / 2;
  double d = sqrt(max(sqr(r) - sqr(mid.x) - sqr(mid.y), 0.0));
  if (eq(d, 0.0)) {
    res[0] = res[1] = mid;
    return;
  }
  point v(mid.y, -mid.x);
  v = v / v.norm();
  res[0] = mid + v * d;
  res[1] = mid - v * d;
}
bool check(double r) {
  p.clear();
  for (int i = 0; i < n; ++i) {
    can[i] = false;
    if (eq(x[i], 0) && eq(y[i], 0)) {
      continue;
    }
    if (sqr(x[i]) + sqr(y[i]) - 4 * sqr(r) > eps) {
      continue;
    }
    point inter[2];
    build_inter(point(x[i], y[i]), r, inter);
    assert(eq(inter[0].norm(), r));
    assert(eq(inter[1].norm(), r));
    assert(eq((inter[0] - point(x[i], y[i])).norm(), r));
    assert(eq((inter[1] - point(x[i], y[i])).norm(), r));
    p.push_back(make_pair(inter[0], make_pair(i, 0)));
    p.push_back(make_pair(inter[1], make_pair(i, 1)));
  }
  sort((p).begin(), (p).end(), vec_cmp);
  int nk = k;
  for (int it = 0; it < 2; ++it) {
    int i = 0;
    while (i < ((int)(p).size())) {
      int j = i;
      while (j + 1 < ((int)(p).size()) && eq(p[i].first.x, p[j + 1].first.x) &&
             eq(p[i].first.y, p[j + 1].first.y)) {
        ++j;
      }
      for (int k = i; k <= j; ++k) {
        if (p[k].second.second == 0) {
          if (!can[p[k].second.first]) {
            can[p[k].second.first] = true;
            --nk;
            if (nk <= 0) {
              return true;
            }
          }
        }
      }
      for (int k = i; k <= j; ++k) {
        if (p[k].second.second == 1) {
          if (can[p[k].second.first]) {
            can[p[k].second.first] = false;
            ++nk;
          }
        }
      }
      i = j + 1;
    }
  }
  return false;
}
void solve() {
  scanf("%d %d", &n, &k);
  for (int i = 0; i < n; ++i) {
    scanf("%lf %lf", x + i, y + i);
    if (eq(x[i], 0) && eq(y[i], 0)) {
      --k;
    }
  }
  if (k <= 0) {
    printf("0\n");
    return;
  }
  double l = 0, r = 2e5;
  for (int it = 0; it < ITERS; ++it) {
    double mid = (l + r) / 2;
    if (check(mid)) {
      r = mid;
    } else {
      l = mid;
    }
  }
  printf("%.09lf\n", (l + r) / 2);
}
int main() {
  init();
  int t = 1;
  for (int i = 0; i < t; ++i) {
    solve();
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 2e3 + 5;
int n, m, mp[N][N], pre[N], qu[N], head, tail;
long long dp[N][N];
char ch[N];
long double slope(int fi, int se, int id) {
  long double X1 = 2 * fi, Y1 = fi * fi + (id - pre[fi]) * (id - pre[fi]);
  long double X2 = 2 * se, Y2 = se * se + (id - pre[se]) * (id - pre[se]);
  return (Y1 - Y2) / (X1 - X2);
}
void work() {
  for (int j = 1; j <= m; j++) pre[j] = -2 * n;
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++)
      if (mp[i][j]) pre[j] = i;
    tail = 0, head = 1;
    for (int j = 1; j <= m; j++) {
      while (2 <= tail &&
             slope(qu[tail - 1], qu[tail], i) > slope(qu[tail], j, i))
        tail--;
      qu[++tail] = j;
    }
    if (head > tail) continue;
    for (int j = 1; j <= m; j++) {
      while (head + 1 <= tail && slope(qu[head], qu[head + 1], i) < j) head++;
      int nw = qu[head];
      dp[i][j] = min(dp[i][j], 1ll * (j - nw) * (j - nw) +
                                   1ll * (i - pre[nw]) * (i - pre[nw]));
    }
  }
}
int main() {
  scanf("%d%d", &n, &m);
  n++;
  m++;
  memset(dp, 0x3f, sizeof(dp));
  for (int i = 1; i <= n; i++) {
    scanf("%s", ch + 1);
    for (int j = 1; j <= m; j++) mp[i][j] = ch[j] - '0';
  }
  work();
  for (int i = 1; i <= (n / 2); i++)
    swap(mp[i], mp[n - i + 1]), swap(dp[i], dp[n - i + 1]);
  work();
  long long ans = 0;
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++) ans += dp[i][j];
  printf("%lld\n", ans);
  return 0;
}
#include <bits/stdc++.h>
using namespace std;
const int nmax = 2e3 + 42;
int n, m;
int inp[nmax][nmax];
int up[nmax];
int mem_score[nmax][nmax];
int score[nmax][nmax];
vector<pair<int, int> > lines;
pair<int, int> meet(pair<int, int> line_1, pair<int, int> line_2) {
  return {line_1.second - line_2.second, line_2.first - line_1.first};
}
void add_line(pair<int, int> cur) {
  if (lines.size() && lines.back().second <= cur.second) return;
  while (lines.size() >= 2) {
    pair<int, int> s = meet(lines[lines.size() - 2], lines[lines.size() - 1]);
    pair<int, int> t = meet(lines[lines.size() - 1], cur);
    if (1LL * s.first * t.second <= 1LL * s.second * t.first)
      lines.pop_back();
    else
      break;
  }
  lines.push_back(cur);
}
int pointer = 0;
int exact(pair<int, int> l, int x) { return x * l.first + l.second; }
int eval(int x) {
  while (pointer - 1 >= 0 &&
         exact(lines[pointer], x) > exact(lines[pointer - 1], x))
    pointer--;
  return exact(lines[pointer], x);
}
void solve() {
  for (int i = 1; i <= n; i++)
    for (int j = 1; j <= m; j++) score[i][j] = 1e9;
  for (int j = 1; j <= m; j++) up[j] = -4e3;
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++)
      if (inp[i][j]) up[j] = i;
    lines = {};
    for (int y1 = m; y1 >= 1; y1--) {
      pair<int, int> cur = {-2 * y1, (up[y1] - i) * (up[y1] - i) + y1 * y1};
      add_line(cur);
    }
    pointer = lines.size() - 1;
    for (int y2 = 1; y2 <= m; y2++) score[i][y2] = eval(y2) + y2 * y2;
  }
}
void flip() {
  for (int i = 1; i <= n + 1 - i; i++)
    for (int j = 1; j <= m; j++) swap(inp[i][j], inp[n + 1 - i][j]);
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie();
  cout.tie();
  cin >> n >> m;
