  int left = 2 * index + 1;
  int right = 2 * index + 2;
  int largest = index;
  if (left < size && arr[left] > arr[largest]) largest = left;
  if (right < size && arr[right] > arr[largest]) largest = right;
  if (largest != index) {
    swap(arr[index], arr[largest]);
    max_heapify_array(arr, largest, size);
  }
}
