  double a2 = CrossProduct(MakeVector(P.t, Q.s), MakeVector(P.t, Q.t));
  return Point((P.s.x * a2 + P.t.x * a1) / (a2 + a1),
               (P.s.y * a2 + P.t.y * a1) / (a2 + a1));
