bool judge(pair<int, int> a, pair<int, int> b, pair<int, int> c) {
  if (b == c) return 0;
  if (b.first < min(a.first, c.first) || b.first > max(a.first, c.first))
    return 0;
  if (b.second < min(a.second, c.second) || b.second > max(a.second, c.second))
    return 0;
